//! Read-only conversation queries on [`Node`]: per-conversation history (channel, DM,
//! account), and the unified `history`. Full-text search lives in `search.rs`.
//! All are pure reads that serve plaintext from the sent/received stores — the wire
//! keys are single-use and gone, which IS the forward-secrecy property, not a gap.

use super::conversation::{account_conversation_id, dm_conversation_id};
use super::node::FileHistoryInfo;
use super::{DmEnvelope, HistoryEntry, MessageBody, Node};
use crate::eventlog::event::{ConversationId, EventId};
use crate::identity::device::PublicIdentity;

impl Node {
    /// Accounts with committed sent, received or file-card history, including
    /// cleared/pruned transcripts. Each database read selects at most 128 keys.
    /// Errors preserve uncertainty; callers must never interpret them as absence.
    pub fn accounts_with_ever_history(
        &self,
        accounts: &[String],
    ) -> Result<std::collections::HashSet<String>, super::NodeError> {
        let own = self.account.account_id();
        let mut result = std::collections::HashSet::new();
        for batch in accounts.chunks(128) {
            let conversations: Vec<_> = batch
                .iter()
                .map(|account| account_conversation_id(&own, account))
                .collect();
            let known = super::transcript_repository::ever_history_conversations(
                &self.storage,
                &conversations,
            )?;
            for (account, conversation) in batch.iter().zip(conversations) {
                if known.contains(&conversation) {
                    result.insert(account.clone());
                }
            }
        }
        Ok(result)
    }
